using System;using System.IO;namespace Mapping{    /// <summary>    /// 히로시미 Mapping    /// </summary>    public class ChipMosConverter : MapConverterSkeleton    {        static ChipMosConverter()        {            MapConverterMap.LookupWithDefault("CHIP MOS", new ChipMosConverter());        }        /// <summary>        ///         /// </summary>        public ChipMosConverter()        {        }        /// <summary>        ///         /// </summary>        /// <param name="mapFile"></param>        /// <returns></returns>        public override MapData Read(string mapFile, bool isOriginalMap = false)        {            if (string.IsNullOrWhiteSpace(mapFile))            {                throw new ArgumentNullException(nameof(mapFile));            }            using (FileStream fs = new FileStream(mapFile, FileMode.Open))            {                return this.Read(fs);            }        }        private MapData Read(Stream stream)        {            var data = new byte[stream.Length];            stream.Read(data, 0, data.Length);            byte versionFlag = data[0];            if (versionFlag == 0)            {                return ParseVersion0(data);            }            else if (versionFlag == 2)            {                return ParseVersion1(data);            }            return null;        }        /// <summary>        /// Mapping System은 오른쪽 하단 모서리의 원점을 기준으로 하며 위쪽은 Row+, 왼쪽은 Col+입니다.        /// </summary>        /// <param name="datas"></param>        /// <returns></returns>        private MapData ParseVersion0(byte[] datas)        {            var mapData = new MapData();            mapData.OriginLocation = OriginLocation.LowerRight;            mapData.Rows = datas[1];            mapData.Columns = datas[2];            mapData.LotID = System.Text.Encoding.UTF8.GetString(datas, 5, 20).TrimEnd('\0');            mapData.SubstrateID = System.Text.Encoding.UTF8.GetString(datas, 25, 8).TrimEnd('\0');            int slotNo = datas[33] - 0x30;            slotNo *= 10;            slotNo += (datas[34] - 0x30);            mapData.SlotNo = slotNo;            string waferType = System.Text.Encoding.UTF8.GetString(datas, 37, 12).TrimEnd('\0');            int binKindCount = datas[53];            binKindCount <<= 8;            binKindCount += datas[54];            mapData.NullBin = Bin.CreateNullBin('.');            mapData.Bins = new BinCollection();            mapData.BinCodes = new BinCode[1, 1, mapData.Rows, mapData.Columns];            int index = 55;            for (int i = 0; i < binKindCount; i++)            {                char binCode = (char)((datas[index] << 8) | datas[index + 1]);                index += 2;                Bin bin = new Bin(new BinCode(binCode), true);                mapData.Bins.Add(bin);                int binCount = datas[index];                index++;                binCount <<= 8;                binCount += datas[index];                index++;                for (int j = 0; j < binCount; j++)                {                    int col = datas[index];                    index++;                    int row = datas[index];                    index++;                    // 원점 좌측상단 좌표계 변경                    row = mapData.Rows - 1 - row;                    col = mapData.Columns - 1 - col;                    mapData.BinCodes[0, 0, row, col] = binCode;                }            }            return mapData;        }        private MapData ParseVersion1(byte[] datas)        {            var mapData = new MapData();            mapData.OriginLocation = OriginLocation.LowerRight;            int rows = datas[1];            rows <<= 8;            rows += datas[2];            int columns = datas[3];            columns <<= 8;            columns += datas[4];            mapData.Rows = rows;            mapData.Columns = columns;            mapData.LotID = System.Text.Encoding.UTF8.GetString(datas, 9, 20).TrimEnd('\0');            mapData.SubstrateID = System.Text.Encoding.UTF8.GetString(datas, 29, 8).TrimEnd('\0');            int slotNo = datas[37] - 0x30;            slotNo *= 10;            slotNo += (datas[38] - 0x30);            mapData.SlotNo = slotNo;            string waferType = System.Text.Encoding.UTF8.GetString(datas, 41, 16).TrimEnd('\0');            int binKindCount = datas[61];            binKindCount <<= 8;            binKindCount += datas[62];            mapData.NullBin = Bin.CreateNullBin('.');            mapData.Bins = new BinCollection();            mapData.BinCodes = new BinCode[1, 1, mapData.Rows, mapData.Columns];            int index = 63;            for (int i = 0; i < binKindCount; i++)            {                char binCode = (char)((datas[index] << 8) | datas[index + 1]);                index += 2;                Bin bin = new Bin(new BinCode(binCode), true);                mapData.Bins.Add(bin);                int binCount = datas[index];                index++;                binCount <<= 8;                binCount += datas[index];                index++;                binCount <<= 8;                binCount += datas[index];                index++;                binCount <<= 8;                binCount += datas[index];                index++;                for (int j = 0; j < binCount; j++)                {                    int col = datas[index];                    index++;                    col <<= 8;                    col += datas[index];                    index++;                    int row = datas[index];                    index++;                    row <<= 8;                    row += datas[index];                    index++;                    // 원점 좌측상단 좌표계 변경                    row = mapData.Rows - 1 - row;                    col = mapData.Columns - 1 - col;                    mapData.BinCodes[0, 0, row, col] = binCode;                }            }            return mapData;        }    }}